changeSet.sql:
UPDATE compliance_rules SET effective_from = COALESCE( (SELECT min(dateexecuted) FROM databasechangelog WHERE id = '037-seed-compliance-rules'), (SELECT min(dateexecuted) FROM databasechangelog WHERE filename LIKE '%037-create-and-seed-compliance-rules%'), current_timestamp) WHERE effective_from IS NULL;
UPDATE compliance_rules SET created_at = effective_from WHERE created_at IS NULL;
UPDATE compliance_rules SET updated_at = effective_from WHERE updated_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_compliance_rule_jurisdiction_effective
ON compliance_rules (state, project_type, effective_from)
WHERE active = true;
